-- CCN Exam Room: 200-question council-standard mock exam (October 2026)
-- Run this once in the Supabase SQL Editor. It is safe to run again.
--
-- All 200 questions are EXISTING questions from the app's question bank (no new questions are added),
-- covering the full NMCN CCN curriculum. Nothing from the Gombe papers is used.
-- Section A Applied Sciences (Q1–50), Section B Fundamentals of CCN (Q51–100), Section C Anaesthesia,
-- Emergencies, O&G and Paediatrics (Q101–150), Section D Professional Practice (Q151–200).
-- The Word copies (question paper, and answers with explanations) use the same numbering and answers.
--
-- What it does:
--   1. Finds each of the 200 questions in the bank (same wording, options and answer).
--   2. Creates the exam "CCN Council Mock Exam — 200 Questions" with exactly these 200 questions — or, if an exam with that
--      title already exists, replaces its questions. Default times: 23 Oct 2026 08:00–18:00 (Nigeria
--      time), 200 minutes per student, answers hidden during the exam, score shown at the end.
--      Change the times in the Exam Room admin page if needed, but do NOT press "Pick random questions".
--   3. Removes the 200 hidden questions an earlier version of this script added, if it was run.
--   4. Shows a check: questions_found and questions_in_exam should both be 200.

drop table if exists mock200;
create temporary table mock200 (n int primary key, q text, opts jsonb, ans_idx int, id int);

update mock200 m set id = (
  select min(x.id) from public.questions x
  where regexp_replace(lower(x.q), '[^a-z0-9]', '', 'g') = regexp_replace(lower(m.q), '[^a-z0-9]', '', 'g')
    and x.opts = m.opts and x.ans_idx = m.ans_idx
);

update public.exam_exams
   set question_ids = (select array_agg(id order by n) from mock200 where id is not null)
 where title = 'CCN Council Mock Exam — 200 Questions';

                               show_answers, show_score, max_warnings, shuffle, all_candidates, attempts_allowed)
select 'CCN Council Mock Exam — 200 Questions',
       'This exam has 200 questions covering the full CCN curriculum. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 200 minutes.',
       timestamptz '2026-10-23 08:00:00+01', timestamptz '2026-10-23 18:00:00+01', 200,
       (select array_agg(id order by n) from mock200 where id is not null),
       false, true, 3, true, true, 1
where not exists (select 1 from public.exam_exams where title = 'CCN Council Mock Exam — 200 Questions');

delete from public.questions where source = 'CCN Exam Room Mock — 200 Questions (Oct 2026)' and is_active = false;

-- Check: both numbers should be 200. If not, missing_question_numbers lists which ones were not found.
select (select count(id) from mock200) as questions_found,
       (select cardinality(question_ids) from public.exam_exams where title = 'CCN Council Mock Exam — 200 Questions') as questions_in_exam,
       (select string_agg(n::text, ', ' order by n) from mock200 where id is null) as missing_question_numbers;

drop table if exists mock200;
